import pytest

from fido2.bls12_381 import *


@pytest.mark.slow
def test_pairing_bls12_381():
    # https://www.ietf.org/archive/id/draft-irtf-cfrg-pairing-friendly-curves-14.html#name-test-vectors-of-optimal-ate
    e = CRV_BLS.pairing(CRV_BLS_G1.generator, CRV_BLS_G2.generator)
    assert e.to_bytes() == bytes.fromhex('')


